UPDATE questions q SET code='navy-renumber-'||q.id FROM canonical_navy r WHERE q.id=r.id AND q.code<>r.code;
UPDATE questions q SET code=r.code,source_references=r.sources FROM canonical_navy r WHERE q.id=r.id AND (q.code IS DISTINCT FROM r.code OR q.source_references IS DISTINCT FROM r.sources);
CREATE TRIGGER question_bank_code BEFORE INSERT OR UPDATE OF code,bank_key,subject_id ON questions FOR EACH ROW EXECUTE FUNCTION assign_question_bank_code();
COMMIT;
